import { describe, expect, it } from 'vitest';
import { getFabricDocument } from '../env';
import { collectSheetRules } from './collectSheetRules';

function parse(svg: string): Document {
  const doc = getFabricDocument();
  const parser = new doc.defaultView!.DOMParser();
  return parser.parseFromString(svg.trim(), 'image/svg+xml');
}

describe('collectSheetRules', () => {
  it('collects rules from multiple style elements', () => {
    const doc = parse(`
<svg xmlns="http://www.w3.org/2000/svg">
<style>.blue { fill: blue; }</style>
<style>.red { fill: red; }</style>
</svg>`);
    expect(collectSheetRules(doc)).toEqual({
      '.blue': { fill: 'blue' },
      '.red': { fill: 'red' },
    });
  });

  it('keeps url() paint server values intact', () => {
    const doc = parse(`
<svg xmlns="http://www.w3.org/2000/svg">
<style>.x { fill: url(https://example.com/paint.svg#swatch); }</style>
</svg>`);
    expect(collectSheetRules(doc)).toEqual({
      '.x': { fill: 'url(https://example.com/paint.svg#swatch)' },
    });
  });
});

